wr <- function(d,name) { f <- file.path(OUT,name); tmp <- paste0(f,".tmp"); fwrite(d,tmp); system2("sync",tmp); stopifnot(file.size(tmp)>0,nrow(fread(tmp))==nrow(d)); file.rename(tmp,f); cat("wrote",name,nrow(d),"\n") }
