SRC <- function(s) fifelse(grepl("^first",s),"fs",fifelse(grepl("^recall",s),"rc",fifelse(grepl("^new_lib",s),"nl",fifelse(grepl("^ts_per",s),"ts","unknown"))))
read10x <- function(p) { ft <- as.vector(h5read(p,"/matrix/features/feature_type")); id <- as.vector(h5read(p,"/matrix/features/id")); bc <- as.vector(h5read(p,"/matrix/barcodes")); sh <- as.integer(h5read(p,"/matrix/shape")); ip <- as.integer(h5read(p,"/matrix/indptr")); ix <- as.integer(h5read(p,"/matrix/indices")); x <- as.numeric(h5read(p,"/matrix/data")); m <- Matrix::sparseMatrix(i=ix+1L,p=ip,x=x,dims=sh); dimnames(m) <- list(id,bc); m[which(ft=="Gene Expression"),,drop=FALSE] }
X <- readRDS(file.path(W4,"pb_counts_v4.rds")); META <- fread(file.path(W4,"pb_meta_v4.csv"))[,.(pb_id,library,kind,source,cluster,celltype,n_cells,total_umi)]; stopifnot(identical(colnames(X),META$pb_id)); cat("pilot pseudobulks",ncol(X),"\n")
## ---- new pseudobulks: No_Group units (No_Group cells only); L065 non-epithelial types (L065 had no pseudobulk in the 02_cnv_v4.R run); same-library host-epithelium controls
NEW <- list(); NM <- list(); HALF <- list(); cnt_found <- list()
for (L in LIB3) { k <- C[library_id==L]; wells <- unique(k$gem_well); stopifnot(length(wells)==1); m <- read10x(M[library_id==L & gem_well==wells]$path); stopifnot(identical(rownames(m),rownames(X))); k[,found:=nzchar(source_barcode) & source_barcode %in% colnames(m)]
  add <- function(id,kind,bc,celltype=NA_character_,src=NA_character_,cl=NA_character_) { NEW[[id]] <<- as.numeric(Matrix::rowSums(m[,bc,drop=FALSE])); NM[[id]] <<- data.table(pb_id=id,library=L,kind=kind,source=src,cluster=cl,celltype=celltype,n_cells=length(bc),total_umi=sum(m[,bc,drop=FALSE])) }
  ng <- k[entry_route=="no_group" & release_status=="kept" & cell_type=="Luminal" & found==TRUE]; ng[,c4:=paste0(SRC(cluster_source),"|c",cluster_res3)]; cat(L,"No_Group cells",nrow(ng),"; not in the count source",k[candidate_route=="no_group" & found==FALSE,.N],"\n"); print(ng[,.N,by=c4][order(-N)])
  for (u in ng[,.N,by=c4][N>=15]$c4) { d <- ng[c4==u]; id <- paste0(L,"|",u,"|ng"); add(id,"unit_ng",d$source_barcode,"Luminal",SRC(d$cluster_source[1]),as.character(d$cluster_res3[1])); if (nrow(d)>=MIN_UNIT) { nn <- nrow(d); ii <- integer(0); jj <- integer(0); ui <- match(u,ng[,.N,by=c4][N>=15]$c4); for (s in seq_len(NSPLIT)) { set.seed(s*1e5+ui); h1 <- sort(sample.int(nn,floor(nn/2))); h2 <- setdiff(seq_len(nn),h1); ii <- c(ii,h1,h2); jj <- c(jj,rep(2L*s-1L,length(h1)),rep(2L*s,length(h2))) }; I <- Matrix::sparseMatrix(i=ii,j=jj,x=1,dims=c(nn,2L*NSPLIT)); hm <- as.matrix(m[,d$source_barcode,drop=FALSE]%*%I); storage.mode(hm) <- "integer"; HALF[[id]] <- hm } }
  if (!L %in% META$library) { ne <- k[release_status=="kept" & !cell_type %in% EPI & found==TRUE]; for (ct in sort(unique(ne$cell_type))) { d <- ne[cell_type==ct]; if (nrow(d)>=MIN_UNIT) add(paste0(L,"|ne_",gsub(" ","_",ct)),"nonepi_celltype",d$source_barcode,ct) } }
  host <- k[release_status=="excluded" & found==TRUE & grepl("non-prostate.*(cholangiocyte|hepatocyte)",exclusion_reason)]; host[,tp:=fifelse(grepl("cholangiocyte",exclusion_reason),"cholangiocyte","hepatocyte")]; cat(L,"host-epithelium cells with counts\n"); print(host[,.N,by=.(tp,set_B=remove_set)]); for (tp in unique(host$tp)) { d <- host[host$tp==tp]; if (nrow(d)>=MIN_UNIT) add(paste0(L,"|ctl_",tp),"control_host",d$source_barcode,tp) }; rm(m); invisible(gc()) }
NEWm <- do.call(cbind,NEW); rownames(NEWm) <- rownames(X); NM <- rbindlist(NM); stopifnot(identical(colnames(NEWm),NM$pb_id)); print(NM[,.(pb_id,kind,n_cells,total_umi)])
X2 <- cbind(X,NEWm); META2 <- rbind(META,NM); stopifnot(identical(colnames(X2),META2$pb_id))
## ---- method of 02_cnv_v4.R
MD <- fread(file.path(REV,"repository_files_v28_2026-11-05/sample_metadata.csv"))[,.(library=internal_sample_id,study_short_id,patient_id,disease_state,library_chemistry)]; MD[,chem_group:=fifelse(library_chemistry %in% c("10x 3' v3","10x 3' v3.1"),"10x 3' v3/v3.1",library_chemistry)]; META2 <- merge(META2,MD,by="library",all.x=TRUE,sort=FALSE); META2 <- META2[match(colnames(X2),pb_id)]; stopifnot(identical(colnames(X2),META2$pb_id),!anyNA(META2$disease_state)); META2[,pkey:=paste(study_short_id,patient_id,sep=":")]
Gall <- fread(file.path(REV,"cnv_pseudobulk_pilot_v1/work/gene_positions_gtf.tsv"),header=FALSE,col.names=c("gene_id","gene_name","chrom","start","end","gene_type")); G <- Gall[chrom %in% paste0("chr",c(1:22,"X"))][!grepl("^HLA-|^IG[HKL][VDJC]|^RP[LS][0-9]|^MT-",gene_name)]; G[,chr_i:=match(chrom,paste0("chr",c(1:22,"X")))]; cb <- as.data.table(readRDS("<R_LIBRARY>/circlize/extdata/cytoband_list.rds")[["hg38"]]); setnames(cb,c("chrom","bstart","bend","band","stain")); cen <- cb[substr(band,1,1)=="q",.(cen=min(bstart)),by=chrom]; G <- merge(G,cen,by="chrom"); G[,arm:=paste0(sub("chr","",chrom),fifelse(start<cen,"p","q"))]; setorder(G,chr_i,start); G <- G[gene_id %in% rownames(X2)]
## TMM: the factors of the 02_cnv_v4.R run stay exactly as they were. Each new pseudobulk gets its TMM factor against that run's reference column, on that run's scale. Otherwise appending columns moves the reference column and every factor.
nf0 <- calcNormFactors(DGEList(counts=X))$samples$norm.factors; names(nf0) <- colnames(X); x0 <- X[rowSums(X>0)>0,,drop=FALSE]; f75 <- edgeR:::.calcFactorQuantile(data=x0,lib.size=colSums(X),p=0.75); rc <- if (median(f75)<1e-20) which.max(colSums(sqrt(x0))) else which.min(abs(f75-mean(f75))); chk <- calcNormFactors(DGEList(counts=X),refColumn=rc)$samples$norm.factors; stopifnot(isTRUE(all.equal(unname(chk),unname(nf0)))); cat("pilot TMM reference column",colnames(X)[rc],"\n"); f2 <- calcNormFactors(DGEList(counts=X2),refColumn=rc)$samples$norm.factors; names(f2) <- colnames(X2); cc <- f2[colnames(X)]/nf0; cat("scale ratio range over pilot columns",range(cc),"\n"); stopifnot(max(cc)/min(cc)<1+1e-6); nf <- c(nf0,f2[colnames(NEWm)]/median(cc)); stopifnot(identical(names(nf),colnames(X2))); print(round(nf[colnames(NEWm)],3)); LC <- sweep(X2[G$gene_id,],2,colSums(X2)*nf,"/")*1e6; LC <- log2(LC+1); invisible(gc())
libl <- META2[kind=="lib_luminal" & n_cells>=50]; ref_ids <- function(u,opt) { if (opt=="a") return(META2[kind=="nonepi_celltype" & library==u$library]$pb_id); if (opt=="b") { if (is.na(u$chem_group) || u$chem_group=="") return(character(0)); return(libl[disease_state=="benign" & chem_group==u$chem_group]$pb_id) }; if (opt=="c") return(libl[library %in% YOUNG & pkey!=u$pkey]$pb_id); if (opt=="d") return(libl[pkey==u$pkey & library!=u$library & disease_state %in% c("benign","normal","BPH")]$pb_id) }
ref_v <- function(r) if (length(r)==1) LC[,r] else rowMeans(LC[,r,drop=FALSE])
profile <- function(cnt,eff,vr) { vu <- log2(cnt[G$gene_id]/eff*1e6+1); keep <- vu>EXPR_MIN & vr>EXPR_MIN; g <- G[keep]; d <- pmax(pmin(vu[keep]-vr[keep],CLIP),-CLIP); x <- d-median(d); cna <- smooth.CNA(CNA(cbind(x),g$chr_i,g$start,data.type="logratio",sampleid="u")); set.seed(1); sg <- segment(cna,verbose=0)$output; gseg <- rep(sg$seg.mean,sg$num.mark); stopifnot(length(gseg)==nrow(g)); arm <- data.table(arm=g$arm,v=gseg)[,.(value=mean(v),n_genes=.N),by=arm][n_genes<MIN_ARM_GENES,value:=NA_real_]; list(arm=arm,n_genes=nrow(g),n_seg=nrow(sg)) }
## ---- reproduction check: units of the 02_cnv_v4.R run, this code, this TMM set
PA <- fread(file.path(P4,"tables/arm_values_full_v4.csv.gz")); set.seed(7); rep_u <- c(META2[kind=="unit_d4" & library %in% LIB3]$pb_id,sample(setdiff(META2[kind=="unit_d4"]$pb_id,META2[library %in% LIB3]$pb_id),30)); rj <- rbindlist(lapply(rep_u,function(u) data.table(pb_id=u,option=c("a","b","c")))); RP <- rbindlist(mclapply(seq_len(nrow(rj)),function(i) { u <- rj$pb_id[i]; o <- rj$option[i]; r <- ref_ids(META2[pb_id==u],o); if (!length(r)) return(NULL); p <- profile(X2[,u],sum(X2[,u])*nf[u],ref_v(r)); data.table(pb_id=u,option=o,p$arm) },mc.cores=NC)); cmp <- merge(RP,PA,by=c("pb_id","option","arm"),suffixes=c("_this","_pilot")); rep_sum <- cmp[,.(units=uniqueN(pb_id),arms=.N,max_abs_diff=max(abs(value_this-value_pilot),na.rm=TRUE),median_abs_diff=median(abs(value_this-value_pilot),na.rm=TRUE),pearson=cor(value_this,value_pilot,use="complete.obs"),same_n_genes=mean(n_genes_this==n_genes_pilot)),by=option]; print(rep_sum); wr(rep_sum,"NG_reproduction_of_pilot_units_v2.csv")
## ---- new units and controls
NU <- META2[kind %in% c("unit_ng","control_host")]; JB <- rbindlist(lapply(seq_len(nrow(NU)),function(i) rbindlist(lapply(c("a","b","c","d"),function(o) { r <- ref_ids(NU[i],o); rm_ <- META2[match(r,pb_id)]; data.table(pb_id=NU$pb_id[i],option=o,n_ref_groups=length(r),ref_ids=paste(r,collapse=";"),ref_libraries=paste(unique(rm_$library),collapse=";"),ref_cells=sum(rm_$n_cells),assessable=length(r)>0) })))); wr(JB,"NG_reference_sets_v2.csv"); FJ <- JB[assessable==TRUE]
res <- mclapply(seq_len(nrow(FJ)),function(i) { u <- FJ$pb_id[i]; o <- FJ$option[i]; p <- profile(X2[,u],sum(X2[,u])*nf[u],ref_v(strsplit(FJ$ref_ids[i],";")[[1]])); list(arm=data.table(pb_id=u,option=o,p$arm),s=data.table(pb_id=u,option=o,genes_used=p$n_genes,n_segments=p$n_seg)) },mc.cores=NC); stopifnot(!any(vapply(res,inherits,TRUE,"try-error"))); ARM <- rbindlist(lapply(res,`[[`,"arm")); US <- rbindlist(lapply(res,`[[`,"s"))
AUTO <- function(a) !grepl("^X",a); SS <- ARM[AUTO(arm) & !is.na(value),.(S_autosomal=max(abs(value)),arm_of_S=arm[which.max(abs(value))],value_of_S=value[which.max(abs(value))]),by=.(pb_id,option)]; US <- merge(US,SS,by=c("pb_id","option")); US <- merge(US,NM[,.(pb_id,library,kind,n_cells,total_umi)],by="pb_id"); US[,below_pilot_floor_of_50_cells:=n_cells<MIN_UNIT]
## ---- context from the arm table of the 02_cnv_v4.R run: young and benign units, each option; values only
UV <- fread(file.path(P4,"tables/units_v4.csv"))[definition=="D4"]; PA4 <- PA[pb_id %in% UV$pb_id]; PA4[,class:=UV$class[match(pb_id,UV$pb_id)]]; PA4[,library:=UV$library[match(pb_id,UV$pb_id)]]; DR <- PA4[class %in% c("young donor","benign") & option %in% c("a","b","c") & !is.na(value),.(q05=quantile(value,.05),q95=quantile(value,.95),units=uniqueN(pb_id)),by=.(option,class,arm)]; wr(DR[,.(option,class,arm,q05=round(q05,4),q95=round(q95,4),units)][order(option,class,arm)],"NG_context_young_benign_arm_ranges_v2.csv"); SD <- PA4[option %in% c("a","b","c") & !grepl("^X",arm) & !is.na(value),.(S=max(abs(value))),by=.(pb_id,option,class)][,.(units=.N,S_median=round(median(S),3),S_q95=round(quantile(S,.95),3),S_max=round(max(S),3)),by=.(option,class)][order(option,class)]; print(SD); wr(SD,"NG_context_S_by_class_v2.csv")
rg <- dcast(DR,option+arm~class,value.var=c("q05","q95")); z <- merge(ARM,rg,by=c("option","arm"),all.x=TRUE); z[,outside:=!is.na(value) & !is.na(`q05_benign`) & !is.na(`q05_young donor`) & (value<pmin(q05_benign,`q05_young donor`) | value>pmax(q95_benign,`q95_young donor`))]; US <- merge(US,z[,.(arms_scored=sum(!is.na(value)),arms_outside_young_and_benign_5_95=sum(outside)),by=.(pb_id,option)],by=c("pb_id","option")); setcolorder(US,c("pb_id","library","kind","n_cells","total_umi","below_pilot_floor_of_50_cells","option")); setorder(US,library,kind,pb_id,option); US[,`:=`(S_autosomal=round(S_autosomal,4),value_of_S=round(value_of_S,4))]; print(US[,.(pb_id,n_cells,option,genes_used,n_segments,S_autosomal,arm_of_S,value_of_S,arms_outside_young_and_benign_5_95)]); wr(US,"NG_unit_summary_v2.csv"); ARMo <- z[,.(pb_id,kind=NM$kind[match(pb_id,NM$pb_id)],option,arm,value=round(value,4),n_genes,outside_young_and_benign_5_95=outside)]; ARMo[,ao:=match(sub("[pq]$","",arm),c(1:22,"X"))]; setorder(ARMo,pb_id,option,ao,arm); ARMo[,ao:=NULL]; wr(ARMo,"NG_arm_values_v2.csv"); W <- dcast(ARM,arm~pb_id+option,value.var="value"); W <- W[order(match(sub("[pq]$","",arm),c(1:22,"X")),arm)]; num <- setdiff(names(W),"arm"); W[,(num):=lapply(.SD,round,3),.SDcols=num]; wr(W,"NG_arm_values_wide_v2.csv")
## ---- half-splits: 20 per unit of 50 or more cells, as in 01_pseudobulk_v4.R; factor of the parent unit
HJ <- FJ[pb_id %in% names(HALF)]; hr <- mclapply(seq_len(nrow(HJ)),function(i) { u <- HJ$pb_id[i]; o <- HJ$option[i]; H <- HALF[[u]]; vr <- ref_v(strsplit(HJ$ref_ids[i],";")[[1]]); rr <- rbindlist(lapply(seq_len(NSPLIT),function(s) { a <- H[,2L*s-1L]; b <- H[,2L*s]; names(a) <- names(b) <- rownames(X2); pa <- profile(a,sum(a)*nf[u],vr)$arm; pb <- profile(b,sum(b)*nf[u],vr)$arm; m <- merge(pa,pb,by="arm",suffixes=c("_1","_2")); m <- m[!grepl("^X",arm) & !is.na(value_1) & !is.na(value_2)]; data.table(split=s,r=if (nrow(m)>2 && sd(m$value_1)>0 && sd(m$value_2)>0) cor(m$value_1,m$value_2) else NA_real_,mad=median(abs(m$value_1-m$value_2))) })); data.table(pb_id=u,option=o,median_r_between_halves=round(median(rr$r,na.rm=TRUE),3),median_abs_arm_diff_between_halves=round(median(rr$mad),4),splits=NSPLIT) },mc.cores=NC,mc.preschedule=FALSE); stopifnot(!any(vapply(hr,inherits,TRUE,"try-error"))); HR <- rbindlist(hr)[order(pb_id,option)]; print(HR); wr(HR,"NG_half_split_stability_v2.csv")
## ---- arm r (Pearson on autosomal arms; a description with no event call): against same-library Luminal units of the 02_cnv_v4.R run, and between the new pseudobulks, under the same reference. Same-library units share the reference, so r is not free of it.
awide <- function(d) { w <- dcast(d[!grepl("^X",arm)],arm~pb_id,value.var="value"); m <- as.matrix(w[,-1]); rownames(m) <- w$arm; m }; R1 <- rbindlist(lapply(c("a","b","c"),function(o) { A <- awide(ARM[option==o]); rbindlist(lapply(colnames(A),function(u) { L <- sub("\\|.*","",u); pu <- PA4[library==L & option==o]; if (!nrow(pu)) return(NULL); B0 <- awide(pu[,.(pb_id,arm,value)]); g <- intersect(rownames(A),rownames(B0)); cr <- cor(A[g,u],B0[g,,drop=FALSE],use="pairwise.complete.obs"); data.table(pb_id=u,option=o,same_library_luminal_units=ncol(B0),r_median=round(median(cr,na.rm=TRUE),3),r_min=round(min(cr,na.rm=TRUE),3),r_max=round(max(cr,na.rm=TRUE),3)) })) })); print(R1); if (nrow(R1)) wr(R1[order(pb_id,option)],"NG_arm_r_against_same_library_luminal_units_v2.csv"); R2 <- rbindlist(lapply(c("a","b","c"),function(o) { A <- awide(ARM[option==o]); cm <- cor(A,use="pairwise.complete.obs"); p <- as.data.table(as.table(cm)); setnames(p,c("a","b","r")); p <- p[as.character(a)<as.character(b)]; p[,option:=o]; p[,r:=round(r,3)]; p })); wr(R2[order(option,a,b)],"NG_arm_r_between_new_pseudobulks_v2.csv"); LS <- PA4[library %in% LIB3 & option %in% c("a","b","c") & !grepl("^X",arm) & !is.na(value),.(S=max(abs(value))),by=.(pb_id,library,option)][,.(units=.N,S_median=round(median(S),3),S_min=round(min(S),3),S_max=round(max(S),3)),by=.(library,option)][order(library,option)]; print(LS); wr(LS,"NG_context_S_same_library_luminal_units_v2.csv"); cat("done",round(as.numeric(difftime(Sys.time(),t0,units="mins")),1),"min\n")
